"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Step 0 item 6 (P1 v0.3, section 4): "same sound" groups for the event and decoy recordings.

Landmark fingerprints (pairs of spectral peaks hashed as (f1, f2, dt), as in Wang 2003) match the same audio content
even after re-recording, cropping, gain change, reverberation and noise, but not merely similar sounds. The match
threshold is calibrated, not guessed:
  - positives: degraded copies of sampled clips (crop, gain, synthetic room reverb, pink noise at 5-20 dB SNR, a
    16 kHz round trip) must be found;
  - null: the best match of each clip against clips of a different class (a doorbell and a zipper cannot be the same
    recording) gives the false-match floor.
The threshold is the smallest aligned-match count that keeps the null false-match rate <= 0.1% of clips; detection of
the degraded copies at that threshold is reported. Groups = union of "same uploader" and "fingerprint match".

usage: python -I scripts/step0_fingerprint.py <clip dir> <selection json> <extra clip dir or -> <output json>
"""
import glob
import json
import os
import sys
from collections import defaultdict

import numpy as np
import soundfile as sf
from scipy.ndimage import maximum_filter
from scipy.signal import fftconvolve, resample_poly, stft

SR = 11025
N_FFT, HOP = 1024, 256
PEAKS_PER_S = 50
FAN_OUT, DT_MAX, DF_MAX = 10, 63, 127
COMMON_CAP = 400                      # hashes posted by more clips than this carry no identity


def load(path):
    y, sr = sf.read(path, dtype="float32", always_2d=True)
    y = y.mean(1)
    g = np.gcd(sr, SR)
    return resample_poly(y, SR // g, sr // g).astype(np.float32)


def peaks(y):
    if len(y) < N_FFT:                                   # very short files (one MUSAN clip is under 0.1 s)
        y = np.pad(y, (0, N_FFT - len(y)))
    _, _, z = stft(y, SR, nperseg=N_FFT, noverlap=N_FFT - HOP, boundary=None, padded=False)
    s = 20 * np.log10(np.abs(z) + 1e-9)
    if s.shape[1] < 2:
        return np.zeros((0, 2), int)
    loc = (s == maximum_filter(s, size=(15, 7))) & (s > np.median(s) + 10)
    f, t = np.nonzero(loc)
    keep = max(1, int(PEAKS_PER_S * s.shape[1] * HOP / SR))
    order = np.argsort(-s[f, t])[:keep]
    p = np.stack([t[order], f[order]], 1)
    return p[np.lexsort((p[:, 1], p[:, 0]))]


def hashes(p):
    hs, ts = [], []
    for i in range(len(p)):
        t1, f1 = p[i]
        n = 0
        for j in range(i + 1, len(p)):
            t2, f2 = p[j]
            dt = t2 - t1
            if dt > DT_MAX:
                break
            if dt < 1 or abs(int(f2) - int(f1)) > DF_MAX:
                continue
            hs.append((min(f1, 511) << 15) | (min(f2, 511) << 6) | dt)
            ts.append(t1)
            n += 1
            if n == FAN_OUT:
                break
    return np.array(hs, np.int64), np.array(ts, np.int32)


def fingerprint(y):
    return hashes(peaks(y))


class Index:
    def __init__(self, fps):
        hs = np.concatenate([h for h, _ in fps])
        ts = np.concatenate([t for _, t in fps])
        cl = np.concatenate([np.full(len(h), i, np.int32) for i, (h, _) in enumerate(fps)])
        o = np.argsort(hs, kind="stable")
        self.h, self.t, self.c = hs[o], ts[o], cl[o]
        pair = np.unique(self.h * 16384 + self.c)            # distinct (hash, clip)
        uh, n_clips = np.unique(pair // 16384, return_counts=True)
        self.common = np.sort(uh[n_clips > COMMON_CAP])

    def best(self, h, t, exclude=-1):
        """{clip: max number of hash matches at one time offset} for a query fingerprint."""
        if len(h) == 0:
            return {}
        keep = ~np.isin(h, self.common)
        h, t = h[keep], t[keep]
        lo = np.searchsorted(self.h, h, "left")
        hi = np.searchsorted(self.h, h, "right")
        n = hi - lo
        total = int(n.sum())
        if total == 0:
            return {}
        idx = np.repeat(lo, n) + (np.arange(total) - np.repeat(np.cumsum(n) - n, n))
        qt = np.repeat(t, n)
        clip, off = self.c[idx], self.t[idx].astype(np.int64) - qt
        m = clip != exclude
        key = clip[m].astype(np.int64) * 100000 + (off[m] + 50000)
        u, k = np.unique(key, return_counts=True)
        out = {}
        for kk, cnt in zip((u // 100000).tolist(), k.tolist()):
            if cnt > out.get(kk, 0):
                out[kk] = cnt
        return out


def degrade(y, rng, harsh=True):
    """Light: crop, gain and a 16 kHz round trip (a re-upload or edit). Harsh: also room reverb and pink noise at
    5-20 dB SNR (the same sound re-recorded in another room)."""
    n = len(y)
    a = int(rng.uniform(0, 0.3) * n)
    y = y[a:a + max(SR, int(rng.uniform(0.6, 0.9) * n))] * rng.uniform(0.3, 1.5)
    if not harsh:
        return resample_poly(resample_poly(y, 16000, SR), SR, 16000).astype(np.float32)
    rt60 = rng.uniform(0.2, 0.7)
    tt = np.arange(int(rt60 * SR)) / SR
    rir = rng.standard_normal(len(tt)) * np.exp(-6.9 * tt / rt60)
    rir[0] = 3.0
    y = fftconvolve(y, rir / np.abs(rir).sum() * 4)[:len(y)]
    pink = np.cumsum(rng.standard_normal(len(y)))
    pink -= np.convolve(pink, np.ones(256) / 256, "same")
    snr = rng.uniform(5, 20)
    pink *= np.sqrt(np.mean(y ** 2) / (np.mean(pink ** 2) + 1e-12) / 10 ** (snr / 10))
    y = y + pink
    return resample_poly(resample_poly(y, 16000, SR), SR, 16000).astype(np.float32)


def main(clip_dir, sel_path, extra_dir, out_path):
    sel = json.load(open(sel_path, encoding="utf-8"))
    ids = sorted(k for k in sel if os.path.exists(os.path.join(clip_dir, k + ".wav")))
    extra = sorted(p for ext in ("wav", "ogg", "flac") for p in glob.glob(os.path.join(extra_dir, "*." + ext))) if extra_dir != "-" else []
    names = ids + [os.path.basename(e) for e in extra]
    paths = [os.path.join(clip_dir, k + ".wav") for k in ids] + extra
    cls = [sel[k]["class"] for k in ids] + ["extra"] * len(extra)
    pool = [sel[k].get("pool", sel[k]["class"]) for k in ids] + ["extra"] * len(extra)
    upl = [sel[k]["uploader"] for k in ids] + [f"extra:{os.path.basename(e)}" for e in extra]
    audio = [load(p) for p in paths]
    fps = [fingerprint(y) for y in audio]
    index = Index(fps)
    best = [index.best(h, t, exclude=i) for i, (h, t) in enumerate(fps)]

    # null: best match against clips of a different POOL (phone, doorbell, knock, decoy, vibration): a doorbell and a
    # typing clip cannot be one recording, while two decoy classes (e.g. keyboard and typing) can be mislabelled copies
    null = np.array([max([c for j, c in b.items() if pool[j] != pool[i] and pool[j] != "extra"], default=0)
                     for i, b in enumerate(best) if pool[i] != "extra"])
    thr = 8
    while np.mean(null >= thr) > 0.001:
        thr += 1

    rng = np.random.default_rng(0)
    probe = rng.choice([i for i in range(len(ids))], size=min(300, len(ids)), replace=False)
    counts = {"light": [], "harsh": []}
    for i in probe:
        for level in ("light", "harsh"):
            h, t = fingerprint(degrade(audio[i], rng, harsh=level == "harsh"))
            counts[level].append(index.best(h, t).get(int(i), 0))
    found = {lv: f"{int(np.sum(np.array(c) >= thr))}/{len(c)}" for lv, c in counts.items()}
    count_q = {lv: {q: float(np.quantile(c, q)) for q in (0.1, 0.25, 0.5)} for lv, c in counts.items()}

    parent = list(range(len(names)))

    def root(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    def union(a, b):
        ra, rb = root(a), root(b)
        if ra != rb:
            parent[rb] = ra

    by_up = defaultdict(list)
    for i, u in enumerate(upl):
        by_up[u].append(i)
    for members in by_up.values():
        for m in members[1:]:
            union(members[0], m)
    matches = []
    for i, b in enumerate(best):
        for j, c in b.items():
            if c >= thr and i < j:
                union(i, j)
                matches.append({"a": names[i], "b": names[j], "count": int(c), "class_a": cls[i], "class_b": cls[j],
                                "same_uploader": upl[i] == upl[j]})
    groups = defaultdict(list)
    for i in range(len(names)):
        groups[root(i)].append(names[i])
    gid = {n: f"g{k:04d}" for k, members in enumerate(sorted(groups.values(), key=lambda m: m[0])) for n in members}
    rep = {
        "threshold_aligned_matches": thr,
        "null_quantiles": {q: float(np.quantile(null, q)) for q in (0.5, 0.9, 0.99, 0.999, 1.0)},
        "degraded_copies_found": found,
        "degraded_copy_count_quantiles": count_q,
        "null_false_match_rate_at_threshold": float(np.mean(null >= thr)),
        "n_clips": len(names), "n_groups": len(groups),
        "cross_uploader_matches": [m for m in matches if not m["same_uploader"]],
        "group_of": gid,
        "params": {"sr": SR, "n_fft": N_FFT, "hop": HOP, "peaks_per_s": PEAKS_PER_S, "fan_out": FAN_OUT,
                   "dt_max": DT_MAX, "df_max": DF_MAX, "common_cap": COMMON_CAP},
    }
    json.dump(rep, open(out_path, "w", encoding="utf-8"), indent=1)
    print({k: v for k, v in rep.items() if k not in ("group_of", "cross_uploader_matches")})
    print("cross-uploader matches:", len(rep["cross_uploader_matches"]))
    for m in rep["cross_uploader_matches"][:30]:
        print("  ", m)


if __name__ == "__main__":
    main(*sys.argv[1:5])
